#!/bin/bash
set -e

# Deploy: WhatsApp registration confirmation (auto-send + manual resend)
# Run this from your veda-hmis repo root in Codespaces.

mkdir -p "lib"
echo "" | base64 -d > "lib/whatsapp.js"
echo "Wrote lib/whatsapp.js"

mkdir -p "app/(main)/patients"
echo "" | base64 -d > "app/(main)/patients/actions.js"
echo "Wrote app/(main)/patients/actions.js"

mkdir -p "app/(main)/patients/[id]/edit"
echo "" | base64 -d > "app/(main)/patients/[id]/edit/edit-form.js"
echo "Wrote app/(main)/patients/[id]/edit/edit-form.js"

git add lib/whatsapp.js "app/(main)/patients/actions.js" "app/(main)/patients/[id]/edit/edit-form.js"
git commit -m "Add WhatsApp registration confirmation (auto-send + manual resend)"
git push

echo "Done. Deployed WhatsApp registration integration."
